mapper.select:
select c.credential_code, c.credential_type, r.title, concat('/open/site/v1/media/', m.public_id) as document_url from site_credential c inner join site_credential_revision r on r.revision_id = c.published_revision_id inner join site_media m on m.media_id = r.document_media_id where c.del_flag = '0' and r.revision_state = 'PUBLISHED' and m.media_state = 'AVAILABLE' and m.del_flag = '0'
and c.credential_type = #{credentialType}
order by c.credential_type, r.title limit #{limit}
